-- Network.lua
-- BULDACITY/2 multi-modem network service for OpenComputers 1.7.10.
local component=require("component")
local event=require("event")
local computer=require("computer")
local M={PROTOCOL="BULDACITY/2",PORT=4242,TIMEOUT=12,MAX_WIRELESS_STRENGTH=400,modem=nil,wireless=false,wirelessStrength=0,wirelessAvailable=false,wirelessReady=false,wirelessComponent=nil,relayPath=true,relayCount=0,accessPointCount=0,relayWirelessCount=0,relayDetected=false,relayPathType="NONE",lastPacketDistance=0,server=nil,serverAddress=nil,lastServer=0,serverListening=false,serverCallback=nil,clientListening=false,heartbeatTimer=nil,helloTimer=nil,linked=false,linkSince=0,diagnostics={},lastScan={}}
local function allModems()local r={};for a in component.list("modem",true)do local m=component.proxy(a);if m then r[#r+1]=m end end;return r end
local function modemInfo()local r={};for _,m in ipairs(allModems())do local wireless=type(m.getStrength)=="function"or type(m.setStrength)=="function";local strength=0;if wireless and type(m.setStrength)=="function"then pcall(function()m.setStrength(M.MAX_WIRELESS_STRENGTH)end)end;if wireless and type(m.getStrength)=="function"then pcall(function()strength=m.getStrength()or 0 end)end;local opened=pcall(function()m.open(M.PORT)end);r[#r+1]={address=m.address,type="modem",wireless=wireless,strength=tonumber(strength)or 0,port=M.PORT,open=opened}end;return r end
local function configureModems()local ms=allModems();M.modem=ms[1];M.wireless=false;M.wirelessAvailable=false;M.wirelessReady=false;M.wirelessStrength=0;M.wirelessComponent=nil;for _,m in ipairs(ms)do pcall(function()m.open(M.PORT)end);if type(m.setStrength)=="function"or type(m.getStrength)=="function"then M.wireless=true;M.wirelessAvailable=true;if type(m.setStrength)=="function"then pcall(function()m.setStrength(M.MAX_WIRELESS_STRENGTH)end)end;local s=0;if type(m.getStrength)=="function"then pcall(function()s=m.getStrength()or 0 end)end;if s>M.wirelessStrength then M.wirelessStrength=tonumber(s)or 0;M.wirelessComponent=m.address end end end;M.wirelessReady=M.wirelessStrength>0;return#ms>0,ms end
local function setRepeaters()M.relayCount=0;M.accessPointCount=0;M.relayWirelessCount=0;for a in component.list("relay",true)do local r=component.proxy(a);if r then M.relayCount=M.relayCount+1;if type(r.setStrength)=="function"then pcall(function()r.setStrength(M.MAX_WIRELESS_STRENGTH)end);M.relayWirelessCount=M.relayWirelessCount+1 end;if type(r.setRepeater)=="function"then pcall(function()r.setRepeater(true)end)end end end;for a in component.list("access_point",true)do local r=component.proxy(a);if r then M.accessPointCount=M.accessPointCount+1;if type(r.setStrength)=="function"then pcall(function()r.setStrength(M.MAX_WIRELESS_STRENGTH)end);M.relayWirelessCount=M.relayWirelessCount+1 end;if type(r.setRepeater)=="function"then pcall(function()r.setRepeater(true)end)end end end;M.relayDetected=M.relayCount>0 or M.accessPointCount>0;if M.relayCount>0 and M.accessPointCount>0 then M.relayPathType="RELAY+ACCESS_POINT"elseif M.relayCount>0 then M.relayPathType=M.relayWirelessCount>0 and"WIRELESS_RELAY"or"WIRED_RELAY"elseif M.accessPointCount>0 then M.relayPathType="ACCESS_POINT"else M.relayPathType="NONE"end end
local function initNetwork(port)M.PORT=port or M.PORT;local ok=configureModems();if not ok then M.lastScan={stage="NO_MODEM",ok=false,time=computer.uptime()};return false,"NO_MODEM"end;setRepeaters();M.lastScan={stage="MODEM_READY",ok=true,time=computer.uptime(),modems=modemInfo()};return true,M.wireless and"MULTI-MODEM/WIRELESS:"..M.wirelessStrength or"WIRED" end
function M.init(port)return initNetwork(port)end
function M.address()local ok,a=pcall(computer.address);return ok and a or"unknown"end
function M.packet(kind,data)return{protocol=M.PROTOCOL,kind=kind,sender=M.address(),time=computer.uptime(),data=data or{}}end
function M.valid(p)return type(p)=="table"and p.protocol==M.PROTOCOL and type(p.kind)=="string"end
function M.componentCheck()configureModems();setRepeaters();local ms=modemInfo();return{modemCount=#ms,modems=ms,wirelessAvailable=M.wirelessAvailable,wirelessReady=M.wirelessReady,wirelessComponent=M.wirelessComponent,wirelessStrength=M.wirelessStrength,relayCount=M.relayCount,accessPointCount=M.accessPointCount,relayWirelessCount=M.relayWirelessCount,wireless=M.wireless}end
local function sendEach(address,packet)local sent=0;local last=nil;for _,m in ipairs(allModems())do local ok,res=pcall(function()m.open(M.PORT);return m.send(address,M.PORT,packet)end);if ok and res~=false then sent=sent+1 else last=res end end;return sent,last end
function M.send(address,kind,data)if not address then return false,"NO_ADDRESS"end;local ok=configureModems();if not ok then return false,"NO_MODEM"end;local sent,last=sendEach(address,M.packet(kind,data));return sent>0,sent>0 and nil or tostring(last)end
function M.broadcast(kind,data)local ok=configureModems();if not ok then return false,"NO_MODEM"end;local sent=0;local last=nil;for _,m in ipairs(allModems())do local s,r=pcall(function()m.open(M.PORT);return m.broadcast(M.PORT,M.packet(kind,data))end);if s and r~=false then sent=sent+1 else last=r end end;return sent>0,sent>0 and nil or tostring(last)end
function M.setWirelessStrength(n)n=tonumber(n);if not n then return false,"BAD_STRENGTH"end;local found=false;for _,m in ipairs(allModems())do if type(m.setStrength)=="function"then local ok=pcall(function()m.setStrength(math.max(0,n))end);found=found or ok end end;M:getWirelessStrength();return found,M.wirelessStrength end
function M.getWirelessStrength()local best=0;for _,m in ipairs(allModems())do if type(m.getStrength)=="function"then local s=0;pcall(function()s=m.getStrength()or 0 end);if s>best then best=tonumber(s)or 0;M.wirelessComponent=m.address end end end;M.wirelessStrength=best;M.wirelessAvailable=M.wireless or best>0;M.wirelessReady=best>0;return best end
function M.status()configureModems();setRepeaters();local ms=modemInfo();return{wireless=M.wireless,wirelessAvailable=M.wirelessAvailable,wirelessReady=M.wirelessReady,wirelessComponent=M.wirelessComponent,wirelessStrength=M:getWirelessStrength(),relayReady=M.relayPath,relayDetected=M.relayDetected,relayPathType=M.relayPathType,relayCount=M.relayCount,accessPointCount=M.accessPointCount,relayWirelessCount=M.relayWirelessCount,lastPacketDistance=M.lastPacketDistance or 0,port=M.PORT,protocol=M.PROTOCOL,server=M.serverAddress,linked=M.linked,linkSince=M.linkSince,modemCount=#ms,modems=ms,diagnostics=M.diagnostics,lastScan=M.lastScan}end
function M.getDiagnostics()local r={};for a,d in pairs(M.diagnostics)do r[a]={};for k,v in pairs(d)do r[a][k]=v end end;return r end
local function clientData()return{name=M.name or"BULDACITY CONTROLLER",role="CLIENT",app=M.name or"BULDACITY CONTROLLER",relay=true,relayDetected=M.relayDetected,relayPathType=M.relayPathType,relayCount=M.relayCount,accessPointCount=M.accessPointCount,relayWirelessCount=M.relayWirelessCount,wireless=M.wireless,wirelessAvailable=M.wirelessAvailable,wirelessReady=M.wirelessReady,wirelessComponent=M.wirelessComponent,wirelessStrength=M.wirelessStrength,clientAddress=M.address(),serverAddress=M.serverAddress,linked=M.linked,modems=modemInfo()}end
function M.startClient(name,extra)local ok,mode=initNetwork(M.PORT);if not ok then return false,mode end;M.name=name or"BULDACITY CONTROLLER";M.extra=extra or{};M.extra.name=M.name;M.extra.role="CLIENT";M.extra.app=M.name;M.extra.mode=mode;M.extra.network=M.extra.network~=false;local function hello()M.extra.clientAddress=M.address();M.extra.serverAddress=M.serverAddress;M.extra.linked=M.linked;M.extra.modems=modemInfo();M.broadcast("HELLO",M.extra)end;hello();if not M.clientListening then M.clientListening=true;event.listen("modem_message",function(_,receiver,sender,port,distance,p)if port~=M.PORT or not M.valid(p)then return end;M.lastPacketDistance=tonumber(distance)or 0;local data=p.data or{};if p.kind=="SERVER_HELLO"then M.server=sender;M.serverAddress=sender;M.lastServer=computer.uptime();M.send(sender,"HELLO",M.extra)elseif p.kind=="LINK_ACK"then M.server=sender;M.serverAddress=sender;M.lastServer=computer.uptime();M.linked=true;M.linkSince=M.linkSince>0 and M.linkSince or computer.uptime();M.send(sender,"LINK_CONFIRM",clientData())elseif p.kind=="PING"then M.server=sender;M.serverAddress=sender;M.lastServer=computer.uptime();M.send(sender,"PONG",{name=M.name,role="CLIENT",app=M.name,wireless=M.wireless,wirelessAvailable=M.wirelessAvailable,wirelessReady=M.wirelessReady,wirelessComponent=M.wirelessComponent,wirelessStrength=M.wirelessStrength,relay=true,relayDetected=M.relayDetected,relayPathType=M.relayPathType,relayCount=M.relayCount,accessPointCount=M.accessPointCount,relayWirelessCount=M.relayWirelessCount,linked=M.linked,clientAddress=M.address(),serverAddress=M.serverAddress,id=data.id,modems=modemInfo()})elseif p.kind=="INPUT"and type(data)=="table"then if data.event=="key_down"or data.event=="key_up"then pcall(computer.pushSignal,data.event,sender,data.char or 0,data.code or 0)elseif data.event=="touch"then pcall(computer.pushSignal,"touch",sender,data.x or 1,data.y or 1,data.button or 0)elseif data.event=="scroll"then pcall(computer.pushSignal,"scroll",sender,data.x or 0,data.y or 0,data.button or 0)end elseif p.kind=="SCREEN_REQUEST"and M.sendScreen then M.sendScreen(sender)end;M.lastWirelessReceived=(tonumber(distance)or 0)>0 end)end;if not M.helloTimer then M.helloTimer=event.timer(3,hello,math.huge)end;if not M.heartbeatTimer then M.heartbeatTimer=event.timer(3,function()initNetwork(M.PORT);local data={name=M.name,role="CLIENT",app=M.name,uptime=computer.uptime(),wireless=M.wireless,wirelessAvailable=M.wirelessAvailable,wirelessReady=M.wirelessReady,wirelessComponent=M.wirelessComponent,wirelessStrength=M.wirelessStrength,relay=true,relayReady=M.relayPath,relayDetected=M.relayDetected,relayPathType=M.relayPathType,relayCount=M.relayCount,accessPointCount=M.accessPointCount,relayWirelessCount=M.relayWirelessCount,lastWirelessReceived=M.lastWirelessReceived==true,clientAddress=M.address(),serverAddress=M.serverAddress,linked=M.linked,modems=modemInfo()};if M.serverAddress then M.send(M.serverAddress,"HEARTBEAT",data)else M.broadcast("HEARTBEAT",data)end end,math.huge)end;return true,mode end
function M.sendScreen(address)if not address or not component.isAvailable("gpu")then return false end;local g=component.gpu;local w,h=g.getResolution();M.send(address,"SCREEN_BEGIN",{width=w,height=h});for y=1,h do local cells={};for x=1,w do local ch,fg,bg=g.get(x,y);cells[x]={ch or" ",fg or 0xFFFFFF,bg or 0}end;M.send(address,"SCREEN_ROW",{y=y,cells=cells})end;M.send(address,"SCREEN_END",{width=w,height=h});return true end
function M.startServer(cb)local ok,mode=initNetwork(M.PORT);if not ok then return false,mode end;M.server=true;M.serverCallback=cb or M.serverCallback;if not M.serverListening then M.serverListening=true;event.listen("modem_message",function(_,receiver,sender,port,distance,p)if port~=M.PORT or not M.valid(p)then return end;M.lastPacketDistance=tonumber(distance)or 0;local data=p.data or{};local d=M.diagnostics[sender]or{address=sender};M.diagnostics[sender]=d;if p.kind=="HELLO"or p.kind=="HEARTBEAT"then for k,v in pairs(data)do d[k]=v end;d.address=sender;d.last=computer.uptime();d.distance=tonumber(distance)or 0;d.wireless=d.distance>0 or data.wireless==true;d.linked=data.linked==true or d.linked==true;d.result=d.linked and"LINKED"or"ONLINE";M.send(sender,"LINK_ACK",{serverAddress=M.address(),protocol=M.PROTOCOL,port=M.PORT,linked=true,serverName="BULDACITY TIER-3"});d.pingSent=computer.uptime();M.lastScan={stage="PING_SENT",ok=true,time=d.pingSent,target=sender};M.send(sender,"PING",{from="BULDACITY SERVER",diagnostic=true,id=tostring(d.pingSent)})elseif p.kind=="LINK_CONFIRM"then for k,v in pairs(data)do d[k]=v end;d.address=sender;d.last=computer.uptime();d.distance=tonumber(distance)or d.distance or 0;d.linked=true;d.linkSince=d.linkSince or computer.uptime();d.result="LINKED";d.serverAddress=M.address()elseif p.kind=="PONG"then for k,v in pairs(data)do d[k]=v end;d.address=sender;d.last=computer.uptime();d.lastPong=d.last;d.distance=tonumber(distance)or 0;d.wireless=d.distance>0 or data.wireless==true;d.result="PASS";if d.pingSent then d.latency=(d.last-d.pingSent)*1000 end;M.lastScan={stage="PONG_PASS",ok=true,time=d.last,target=sender,distance=d.distance}elseif p.kind=="COMPONENT_DATA"and type(data)=="table"then for k,v in pairs(data)do d[k]=v end;d.componentCount=tonumber(data.count)or(type(data.components)=="table"and#data.components or 0);d.last=computer.uptime();d.distance=tonumber(distance)or 0;d.wireless=d.distance>0 or data.wireless==true;M.lastScan={stage="COMPONENT_DATA",ok=true,time=d.last,target=sender}end;if M.serverCallback then M.serverCallback(sender,p,distance)end end)end;return true,mode end
return M
